{
  "name": "pi-boomerang",
  "version": "0.7.0",
  "description": "Token-efficient autonomous task execution with context collapse",
  "type": "module",
  "keywords": [
    "pi-package"
  ],
  "files": [
    "index.ts",
    "README.md",
    "CHANGELOG.md",
    "banner.png"
  ],
  "scripts": {
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": ">=0.75.4",
    "typebox": "*"
  },
  "devDependencies": {
    "vitest": "^2.0.0",
    "@earendil-works/pi-coding-agent": "0.83.0",
    "@earendil-works/pi-ai": "0.83.0",
    "typebox": "^1.3.7"
  },
  "pi": {
    "extensions": [
      "./index.ts"
    ]
  }
}

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: false,
    environment: "node",
    include: ["**/*.test.ts"],
    typecheck: {
      enabled: false,
    },
  },
  esbuild: {
    target: "node20",
  },
});
